css:
.theorysim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1b2435;
    background: linear-gradient(160deg, #f3f5f9 0%, #e7ebf3 100%);
    border-radius: 18px;
}

.theorysim-container * {
    box-sizing: border-box;
}

.theorysim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #0e1c33 0%, #1b3a5c 55%, #244a73 100%);
    color: #f4f7fc;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(14, 28, 51, 0.32);
    border-bottom: 3px solid #c9a227;
}

.theorysim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.theorysim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #e9d28a;
    background: rgba(201, 162, 39, 0.16);
    padding: 5px 14px;
    border-radius: 999px;
}

.theorysim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #d6e0ee;
}

.theorysim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2a3b56;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.theorysim-period-counter #currentDay,
.theorysim-period-counter #maxPeriods {
    font-weight: 800;
    color: #0e1c33;
}

.theorysim-round-name {
    background: #d9e2f1;
    color: #0e1c33;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.theorysim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a2f1d;
    background: #f6e1da;
    padding: 4px 12px;
    border-radius: 999px;
}

.theorysim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.theorysim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #d7deeb;
    box-shadow: 0 4px 14px rgba(14, 28, 51, 0.07);
    border-top: 4px solid #244a73;
}

.theorysim-card-coherence { border-top-color: #1b6f54; }
.theorysim-card-discount { border-top-color: #b3361f; }
.theorysim-card-growth { border-top-color: #c9a227; }
.theorysim-card-capital { border-top-color: #2f5d96; }

.theorysim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #5d6b85;
}

.theorysim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #0e1c33;
}

.theorysim-card-coherence .theorysim-value { color: #1b6f54; }
.theorysim-card-discount .theorysim-value { color: #b3361f; }
.theorysim-card-growth .theorysim-value { color: #a9851c; }
.theorysim-card-capital .theorysim-value { color: #2f5d96; }

.theorysim-card-capital .theorysim-value {
    font-size: 1.5rem;
}

.theorysim-sublabel {
    font-size: 0.76rem;
    color: #6f7d97;
    line-height: 1.35;
}

.theorysim-coherence-strong .theorysim-value { color: #1b6f54; }
.theorysim-coherence-weak .theorysim-value { color: #b3361f; }

.theorysim-discount-closed .theorysim-value { color: #1b6f54; }
.theorysim-discount-wide .theorysim-value { color: #b3361f; }

.theorysim-capital-over { border-top-color: #b3361f; }
.theorysim-capital-over .theorysim-value { color: #b3361f; }

.theorysim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #0e1c33;
    color: #eef3fb;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.theorysim-budget-bar #leverageDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #e9d28a;
}

.theorysim-budget-bar.theorysim-leverage-breach #leverageDisplay {
    color: #ff8a72;
}

.theorysim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #c9a227;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(14, 28, 51, 0.06);
}

.theorysim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.theorysim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #0e1c33;
    margin-bottom: 6px;
}

.theorysim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #2c3a52;
}

.theorysim-briefing-text strong { color: #1b6f54; }
.theorysim-briefing-text em { color: #8a2f1d; font-style: italic; }

.theorysim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d7deeb;
    box-shadow: 0 4px 14px rgba(14, 28, 51, 0.07);
}

.theorysim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #0e1c33;
    border-bottom: 2px solid #e7ebf3;
    padding-bottom: 8px;
}

.theorysim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #1e2c44;
    margin: 14px 0 6px;
}

.theorysim-container select,
.theorysim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #bccadd;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f7f9fd;
    color: #1b2435;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.theorysim-container select:focus,
.theorysim-container input[type="number"]:focus {
    outline: none;
    border-color: #244a73;
    box-shadow: 0 0 0 3px rgba(36, 74, 115, 0.15);
}

.theorysim-container select option {
    background-color: #ffffff;
    color: #1b2435;
}

.theorysim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #c9a227;
}

.theorysim-range-readout,
.theorysim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #244a73;
    margin-top: 4px;
}

.theorysim-range-readout span:last-child,
.theorysim-alloc-readout span:nth-child(2) {
    color: #1b6f54;
    font-weight: 800;
}

.theorysim-hint {
    font-size: 0.8rem;
    color: #6f7d97;
    margin-top: 4px;
    line-height: 1.4;
}

.theorysim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.theorysim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f4f7fb;
    border: 1px solid #dde5f0;
    border-radius: 9px;
    padding: 8px 12px;
}

.theorysim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #1e2c44;
}

.theorysim-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.theorysim-bet-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 6px;
}

.theorysim-bet-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f4f7fb;
    border: 1px solid #dde5f0;
    border-radius: 9px;
    padding: 10px 14px;
    font-weight: 600;
    cursor: pointer;
    margin: 0;
}

.theorysim-bet-row input[type="checkbox"] {
    width: 18px;
    height: 18px;
    flex: 0 0 18px;
    accent-color: #1b6f54;
}

.theorysim-bet-name {
    flex: 1;
    font-size: 0.88rem;
    color: #1e2c44;
}

.theorysim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.theorysim-container .btn-primary {
    background: linear-gradient(135deg, #1b3a5c 0%, #244a73 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(27, 58, 92, 0.28);
}

.theorysim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.theorysim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #bccadd;
    color: #5d6b85;
}

.theorysim-coach {
    background: #0e1c33;
    color: #eef3fb;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(14, 28, 51, 0.24);
    border-left: 5px solid #c9a227;
}

.theorysim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e9d28a;
    margin-bottom: 8px;
}

.theorysim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.theorysim-coach-body strong { color: #f0d98c; }
.theorysim-coach-body em { color: #ffb39c; font-style: italic; }

.theorysim-history,
.theorysim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d7deeb;
    box-shadow: 0 4px 14px rgba(14, 28, 51, 0.07);
}

.theorysim-history h3,
.theorysim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #0e1c33;
}

.theorysim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #1e2c44;
}

.theorysim-container table#usfHistoryTable th {
    background: #eaeff7;
    color: #0e1c33;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d4ddec;
}

.theorysim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef2f8;
}

.theorysim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f7f9fd;
}

.theorysim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .theorysim-container {
        padding: 14px;
    }
    .theorysim-header h1 {
        font-size: 1.7rem;
    }
    .theorysim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .theorysim-value {
        font-size: 2rem;
    }
    .theorysim-card-capital .theorysim-value {
        font-size: 1.25rem;
    }
    .theorysim-clock {
        margin-left: 0;
    }
    .theorysim-period-counter {
        font-size: 0.88rem;
    }
    .theorysim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .theorysim-alloc-row {
        flex-wrap: wrap;
    }
    .theorysim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .theorysim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 completion debrief (append-only, self-contained) ===== */
.theorysim-cm { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #2a2410; text-align: center; padding: 4px 2px 8px; }
.theorysim-cm-title { font-size: 20px; font-weight: 700; color: #6e5410; margin-bottom: 14px; }
.theorysim-cm-scorewrap { background: linear-gradient(135deg, #6e5410 0%, #b0862f 55%, #d8b45f 100%); color: #fcf8f0; border-radius: 14px; padding: 18px 16px; margin: 0 auto 16px; max-width: 420px; }
.theorysim-cm-score { font-size: 46px; font-weight: 800; line-height: 1; }
.theorysim-cm-score-max { font-size: 20px; font-weight: 600; opacity: 0.85; }
.theorysim-cm-grade { font-size: 18px; font-weight: 700; margin-top: 8px; }
.theorysim-cm-badges { margin-top: 10px; }
.theorysim-cm-badge { display: inline-block; font-size: 12px; font-weight: 700; padding: 4px 12px; border-radius: 999px; }
.theorysim-cm-badge-ok { background: #efe2c4; color: #6e5410; }
.theorysim-cm-badge-miss { background: #f3d8d2; color: #9a3016; }
.theorysim-cm-kpis { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin: 0 auto 14px; max-width: 460px; }
.theorysim-cm-kpi { flex: 1 1 120px; min-width: 120px; background: #faf6ee; border: 1px solid #efe2c4; border-radius: 10px; padding: 10px 6px; }
.theorysim-cm-kpi-val { font-size: 20px; font-weight: 700; color: #7e5f1a; }
.theorysim-cm-kpi-lbl { font-size: 11px; font-weight: 600; color: #6a6250; text-transform: uppercase; letter-spacing: .3px; margin-top: 2px; }
.theorysim-cm-insights { text-align: left; max-width: 520px; margin: 0 auto; background: #fbf8f2; border-left: 4px solid #b0862f; border-radius: 8px; padding: 12px 16px; }
.theorysim-cm-ins-h { font-weight: 700; color: #6e5410; margin-bottom: 6px; font-size: 14px; }
.theorysim-cm-insights ul { margin: 0; padding-left: 18px; }
.theorysim-cm-insights li { font-size: 13px; line-height: 1.5; margin-bottom: 6px; color: #34301f; }
@media (max-width: 480px) { .theorysim-cm-kpi { flex-basis: 45%; } .theorysim-cm-score { font-size: 38px; } .theorysim-cm-scorewrap { max-width: 100%; } }

