(function() {
    'use strict';

    class CorporateTheoryAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Your Corporate Theory`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (USD, $m).
            this.START_COHERENCE = 30;       // latent logic exists but is unarticulated
            this.START_DISCOUNT = 22;        // conglomerate discount, %
            this.DISCOUNT_FLOOR = 11;        // half of 22% closable (~$370m of equity value)
            this.START_GROWTH = 35;          // organic growth stuck at 2%
            this.CAPITAL_CEILING = 1000;     // ~$1.0bn within prudent leverage
            this.START_LEVERAGE = 1.8;       // net debt / EBITDA today
            this.LEVERAGE_CEILING = 3.0;     // hard ceiling
            this.EBITDA = 660;               // $m, used for leverage calc
            this.LEVERAGE_FACTOR = 0.5;      // share of each committed $ that adds to net debt
            this.TARGET_COHERENCE = 70;      // a credible, narrow theory

            // Bet sizes, $m.
            this.BET = { hydro: 620, software: 180, apex: 240, verdana: 410 };

            // Concept truths.
            this.TRUE_TISSUE = `sensing`;
            this.TRUE_MISFIT = `robotics`;
            this.TRUE_CAUSE = `logic`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    coherence: this.START_COHERENCE,
                    discount: this.START_DISCOUNT,
                    growth: this.START_GROWTH,
                    capitalCommitted: 0,
                    leverage: this.START_LEVERAGE,
                    leverageBreach: false,
                    fundedVerdana: false,
                    rejectedTrap: false,
                    coherenceHistory: [this.START_COHERENCE],
                    discountHistory: [this.START_DISCOUNT],
                    growthHistory: [this.START_GROWTH],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Middling / neutral seed — NOT the textbook-correct play.
                state.decisions = {
                    tissue: `sensing`,
                    misfit: `software`,
                    discountCause: `ir`,
                    rigor: 50,
                    theory: `broad`,
                    foresight: 34,
                    insight: 33,
                    crosssight: 33,
                    boundary: `lowmargin`,
                    fundHydro: true,
                    fundSoftware: true,
                    fundApex: false,
                    fundVerdana: true,
                    rejection: `financials`,
                    sequence: `growthFirst`,
                    defend: `concede`,
                    value: `eps`,
                    proof: `vague`,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const tissue = document.getElementById(`tissueInput`);
                const misfit = document.getElementById(`misfitInput`);
                const cause = document.getElementById(`discountCauseInput`);
                const rigor = document.getElementById(`rigorInput`);
                if (tissue) decisions.tissue = tissue.value;
                if (misfit) decisions.misfit = misfit.value;
                if (cause) decisions.discountCause = cause.value;
                if (rigor) decisions.rigor = parseInt(rigor.value, 10);
                if (!Number.isFinite(decisions.rigor) || decisions.rigor < 0 || decisions.rigor > 100) {
                    warn(`warn_rigor_range`); return false;
                }
            } else if (round === 2) {
                const theory = document.getElementById(`theoryInput`);
                const boundary = document.getElementById(`boundaryInput`);
                if (theory) decisions.theory = theory.value;
                if (boundary) decisions.boundary = boundary.value;
                const fs = document.getElementById(`foresightInput`);
                const ins = document.getElementById(`insightInput`);
                const cs = document.getElementById(`crosssightInput`);
                if (fs) decisions.foresight = parseFloat(fs.value);
                if (ins) decisions.insight = parseFloat(ins.value);
                if (cs) decisions.crosssight = parseFloat(cs.value);
                const parts = [decisions.foresight, decisions.insight, decisions.crosssight];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_emphasis_negative`); return false;
                }
                const total = Math.round(decisions.foresight + decisions.insight + decisions.crosssight);
                if (total !== 100) {
                    warn(`warn_emphasis_total`); return false;
                }
            } else if (round === 3) {
                const h = document.getElementById(`betHydroInput`);
                const s = document.getElementById(`betSoftwareInput`);
                const a = document.getElementById(`betApexInput`);
                const v = document.getElementById(`betVerdanaInput`);
                if (h) decisions.fundHydro = h.checked;
                if (s) decisions.fundSoftware = s.checked;
                if (a) decisions.fundApex = a.checked;
                if (v) decisions.fundVerdana = v.checked;
                const rej = document.getElementById(`rejectionInput`);
                const seq = document.getElementById(`sequenceInput`);
                if (rej) decisions.rejection = rej.value;
                if (seq) decisions.sequence = seq.value;
                const anyFunded = decisions.fundHydro || decisions.fundSoftware || decisions.fundApex || decisions.fundVerdana;
                if (!anyFunded) {
                    warn(`warn_nofund`); return false;
                }
            } else if (round === 4) {
                const def = document.getElementById(`defendInput`);
                const val = document.getElementById(`valueInput`);
                const pr = document.getElementById(`proofInput`);
                const cv = document.getElementById(`convictionInput`);
                if (def) decisions.defend = def.value;
                if (val) decisions.value = val.value;
                if (pr) decisions.proof = pr.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // coherenceDelta = how much tighter capital follows one logic.
            // growthDelta    = what the impatient board feels short-term.
            // spend          = $m committed this round.
            let coherenceDelta = 0, growthDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: find the latent connective tissue, name the misfit, read the discount.
                if (d.tissue === this.TRUE_TISSUE) {
                    coherenceDelta += 14; coachKey = `coach_r1_tissue_right`;
                } else if (d.tissue === `opex` || d.tissue === `brand`) {
                    coherenceDelta += 2; coachKey = `coach_r1_tissue_generic`;
                } else {
                    coherenceDelta -= 8; coachKey = `coach_r1_tissue_none`;
                }

                if (d.misfit === this.TRUE_MISFIT) {
                    coherenceDelta += 8;
                    if (d.tissue === this.TRUE_TISSUE) coachKey = `coach_r1_diag_sharp`;
                } else if (d.misfit === `nofit`) {
                    coherenceDelta -= 8; coachKey = `coach_r1_nofit`;
                } else {
                    coherenceDelta -= 2;
                }

                if (d.discountCause === this.TRUE_CAUSE) {
                    coherenceDelta += 6;
                } else if (d.discountCause === `ir`) {
                    coherenceDelta -= 2; coachKey = `coach_r1_ir`;
                } else {
                    coherenceDelta -= 4; coachKey = `coach_r1_size`;
                }

                // Rigor: doing the archaeology before reaching for the pipeline.
                if (d.rigor >= 60) { coherenceDelta += 6; }
                else if (d.rigor <= 25) { coherenceDelta -= 6; growthDelta -= 2; coachKey = `coach_r1_lowrigor`; }

                summaryKey = (d.tissue === this.TRUE_TISSUE && d.misfit === this.TRUE_MISFIT) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Articulate a narrow, falsifiable, distinctive theory.
                switch (d.theory) {
                    case `narrow`: coherenceDelta += 16; coachKey = `coach_r2_narrow`; break;
                    case `broad`: coherenceDelta -= 6; coachKey = `coach_r2_broad`; break;
                    case `growth`: coherenceDelta -= 4; growthDelta += 6; coachKey = `coach_r2_growth`; break;
                    case `breakup`: coherenceDelta -= 12; growthDelta -= 6; coachKey = `coach_r2_breakup`; break;
                }

                // Zenger's three components: cross-sight is the binding piece for this portfolio,
                // but all three must be meaningfully present. Neglecting any one weakens the theory.
                const minComp = Math.min(d.foresight, d.insight, d.crosssight);
                if (minComp >= 25 && d.crosssight >= 30) {
                    coherenceDelta += 10;
                    if (d.theory === `narrow`) coachKey = `coach_r2_balanced`;
                } else if (minComp >= 15) {
                    coherenceDelta += 4;
                } else {
                    coherenceDelta -= 6; coachKey = `coach_r2_lopsided`;
                }

                // Boundary: a theory that rejects nothing predicts nothing.
                switch (d.boundary) {
                    case `nooverlap`: coherenceDelta += 8; break;
                    case `lowmargin`: coherenceDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r2_lowmargin` : coachKey; break;
                    case `nothing`: coherenceDelta -= 10; growthDelta += 2; coachKey = `coach_r2_nobound`; break;
                }

                summaryKey = (d.theory === `narrow` && d.boundary === `nooverlap`) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Allocate capital under the ~$1.0bn ceiling; reject the incoherent bet.
                if (d.fundHydro) spend += this.BET.hydro;
                if (d.fundSoftware) spend += this.BET.software;
                if (d.fundApex) spend += this.BET.apex;
                if (d.fundVerdana) spend += this.BET.verdana;

                // Strategic-fit scoring of the funded portfolio.
                if (d.fundSoftware) coherenceDelta += 10;   // organic build = highest coherence
                if (d.fundHydro) coherenceDelta += 9;        // sensing into water = coherent
                if (d.fundApex) { coherenceDelta += 1; growthDelta += 2; } // neutral bolt-on, accretive
                if (d.fundVerdana) {                          // the growth trap
                    coherenceDelta -= 16; growthDelta += 14; ds.fundedVerdana = true;
                    coachKey = `coach_r3_verdana`;
                }

                // The coherent build is slow on near-term EPS — modest growth signal.
                if (d.fundSoftware && !d.fundVerdana) growthDelta += 1;
                if (d.fundHydro) growthDelta += 3;

                // Capital discipline: over the ceiling breaches the leverage cushion.
                if (spend > this.CAPITAL_CEILING) {
                    coherenceDelta -= 8; growthDelta -= 4;
                    if (!ds.fundedVerdana) coachKey = `coach_r3_overcap`;
                    else coachKey = `coach_r3_overcap_verdana`;
                }

                // Rejection discipline: a theory-based "no" is the test of the strategy.
                if (d.rejection === `theory` && !d.fundVerdana) {
                    coherenceDelta += 10; ds.rejectedTrap = true; coachKey = `coach_r3_reject_theory`;
                } else if (d.rejection === `theory` && d.fundVerdana) {
                    coherenceDelta -= 4; coachKey = `coach_r3_reject_contradiction`;
                } else if (d.rejection === `financials`) {
                    coherenceDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r3_reject_financials` : coachKey;
                } else if (d.rejection === `none`) {
                    coherenceDelta -= 8; growthDelta += 2; coachKey = `coach_r3_reject_none`;
                }

                // Sequencing.
                switch (d.sequence) {
                    case `coreFirst`: coherenceDelta += 6; break;
                    case `boltFirst`: coherenceDelta -= 2; growthDelta += 2; break;
                    case `growthFirst`: coherenceDelta -= 4; growthDelta += 4; coachKey = (coachKey === `coach_default`) ? `coach_r3_growthfirst` : coachKey; break;
                }

                const cleanPortfolio = d.fundHydro && d.fundSoftware && !d.fundVerdana && spend <= this.CAPITAL_CEILING;
                summaryKey = cleanPortfolio ? `sum_r3_good` : (d.fundVerdana ? `sum_r3_trap` : `sum_r3_weak`);
            } else if (round === 4) {
                // Defend coherence; quantify it; commit to a falsifiable proof point.
                switch (d.defend) {
                    case `discipline`: coherenceDelta += 12; growthDelta += 2; coachKey = `coach_r4_discipline`; break;
                    case `concede`: coherenceDelta -= 12; growthDelta += 10; ds.fundedVerdana = true; coachKey = `coach_r4_concede`; break;
                    case `breakup`: coherenceDelta -= 16; growthDelta -= 4; coachKey = `coach_r4_breakup`; break;
                }

                switch (d.value) {
                    case `discountclose`: coherenceDelta += 8; break;
                    case `eps`: coherenceDelta -= 4; growthDelta += 4; coachKey = (coachKey === `coach_default`) ? `coach_r4_eps` : coachKey; break;
                    case `tam`: coherenceDelta -= 6; growthDelta += 4; coachKey = (coachKey === `coach_default`) ? `coach_r4_tam` : coachKey; break;
                }

                switch (d.proof) {
                    case `cross`: coherenceDelta += 10; coachKey = (d.defend === `discipline`) ? `coach_r4_proof` : coachKey; break;
                    case `vague`: coherenceDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r4_vague` : coachKey; break;
                    case `none`: coherenceDelta -= 8; coachKey = (coachKey === `coach_default`) ? `coach_r4_noproof` : coachKey; break;
                }

                // Conviction nudges coherence (defending the disciplined "no").
                coherenceDelta += Math.round((d.conviction - 60) / 8);

                summaryKey = (d.defend === `discipline` && d.value === `discountclose` && d.proof === `cross`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Apply deltas ----
            ds.coherence = Math.max(0, Math.min(100, ds.coherence + coherenceDelta));
            ds.growth = Math.max(0, Math.min(100, ds.growth + growthDelta));

            // Capital / leverage accounting (round 3 only adds spend, but recompute every round).
            // New bets are funded with a debt/equity/cash mix: only LEVERAGE_FACTOR of each
            // committed dollar adds to net debt. Calibrated so the ~$1.0bn ceiling lands at the
            // 2.5x practical limit and the full $1.45bn of bets pushes net debt to ~2.9x.
            ds.capitalCommitted = Math.round(ds.capitalCommitted + spend);
            ds.leverage = Math.round((this.START_LEVERAGE + (ds.capitalCommitted * this.LEVERAGE_FACTOR) / this.EBITDA) * 100) / 100;
            // "Breach" = over the prudent ~$1.0bn ceiling, eroding the cushion to the 3.0x limit.
            ds.leverageBreach = ds.capitalCommitted > this.CAPITAL_CEILING;

            // Conglomerate discount tracks coherence: a credible theory closes it toward the floor,
            // incoherence widens it back toward 22%+. Funded incoherent growth widens it further.
            const targetDiscount = this.START_DISCOUNT - (this.START_DISCOUNT - this.DISCOUNT_FLOOR) * (ds.coherence / 100);
            // ease the discount toward its coherence-implied target
            ds.discount = Math.round((ds.discount + (targetDiscount - ds.discount) * 0.7) * 10) / 10;
            if (ds.fundedVerdana) ds.discount = Math.min(this.START_DISCOUNT + 2, ds.discount + 1.5);
            if (ds.leverageBreach) ds.discount = Math.min(this.START_DISCOUNT + 2, ds.discount + 1.0);
            ds.discount = Math.max(this.DISCOUNT_FLOOR, Math.min(this.START_DISCOUNT + 2, ds.discount));

            ds.coherenceHistory.push(Math.round(ds.coherence));
            ds.discountHistory.push(Math.round(ds.discount * 10) / 10);
            ds.growthHistory.push(Math.round(ds.growth));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0: persist composite so express_resolveDomainScore (domainState.performance.overallScore) resolves.
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                coherence: Math.round(ds.coherence),
                coherenceDelta: Math.round(coherenceDelta),
                discount: Math.round(ds.discount * 10) / 10,
                growth: Math.round(ds.growth),
                growthDelta: Math.round(growthDelta),
                capitalCommitted: ds.capitalCommitted,
                leverage: ds.leverage,
                leverageBreach: ds.leverageBreach,
                fundedVerdana: ds.fundedVerdana,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

