                if (el) el.addEventListener(`input`, recomputeEmp);
            });
            recomputeEmp();

            // Capital-selected live total in round 3.
            const betMap = { betHydroInput: this.BET.hydro, betSoftwareInput: this.BET.software, betApexInput: this.BET.apex, betVerdanaInput: this.BET.verdana };
            const spendReadout = document.getElementById(`spendReadout`);
            const recomputeSpend = function() {
                let total = 0;
                Object.keys(betMap).forEach((id) => {
                    const el = document.getElementById(id);
                    if (el && el.checked) total += betMap[id];
                });
                if (spendReadout) {
