                    spendReadout.style.color = (total > self.CAPITAL_CEILING) ? `#b3361f` : `#1b6f54`;
                }
            };
            Object.keys(betMap).forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`change`, recomputeSpend);
            });
            recomputeSpend();
        }

