        // v1.1.0: single source of truth for the composite (verbatim v1.0.0 formula).
        _composite(ds) {
            const coherence = Math.round(ds.coherence);
            const discount = Math.round(ds.discount * 10) / 10;
            const growth = Math.round(ds.growth);
            const discountScore = Math.max(0, Math.min(100, (this.START_DISCOUNT - discount) / (this.START_DISCOUNT - this.DISCOUNT_FLOOR) * 100));
            const trapPenalty = (ds.fundedVerdana ? 22 : 0) + (ds.leverageBreach ? 14 : 0);
            return Math.max(0, Math.round(coherence * 0.5 + discountScore * 0.35 + growth * 0.15 - trapPenalty));
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const coherence = Math.round(ds.coherence);
            const discount = Math.round(ds.discount * 10) / 10;
            const growth = Math.round(ds.growth);

            const credibleTheory = coherence >= this.TARGET_COHERENCE;
            const discountClosed = discount <= 16;
            const fundedTrap = ds.fundedVerdana;
            const breach = ds.leverageBreach;
            // Composite rewards coherence + discount closure; growth is a tie-breaker, not the goal.
            // The growth trap (Verdana) and the leverage breach are the defining errors of this
            // concept: opportunistic growth that destroys corporate value. A late-round coherence
            // recovery can re-peg the 0–100 meter at its clamp, so we subtract a persistent penalty
            // here to keep that scar visible on the final composite — the discount may ease back, but
            // the scoreboard must not launder a portfolio that chased the incoherent deal.
            const discountScore = Math.max(0, Math.min(100, (this.START_DISCOUNT - discount) / (this.START_DISCOUNT - this.DISCOUNT_FLOOR) * 100));
            const trapPenalty = (fundedTrap ? 22 : 0) + (breach ? 14 : 0);
            const composite = this._composite(ds);

            // Order matters: a portfolio that funded the trap or breached the ceiling can NEVER be
            // labelled "Coherent Portfolio", no matter how high the recovered coherence reads — that
            // outcome is exactly the activist's thesis confirmed. Check the failure modes first.
            let performance = `Incoherent Grab-Bag`, performanceKey = `grade_grabbag`;
            if (fundedTrap) { performance = `Chased the Growth Deal`; performanceKey = `grade_trap`; }
            else if (breach) { performance = `Funded Everything, No Cushion`; performanceKey = `grade_breach`; }
            else if (credibleTheory && discountClosed && composite >= 75) { performance = `Re-Rated on a Theory`; performanceKey = `grade_rerated`; }
            else if (credibleTheory && discountClosed) { performance = `Coherent Portfolio`; performanceKey = `grade_coherent`; }
            else if (coherence > this.START_COHERENCE + 15) { performance = `Sharper but Unproven`; performanceKey = `grade_sharper`; }

            const insights = [];
            if (credibleTheory && discountClosed && !fundedTrap) insights.push(window.mySimulation.t(`insight_rerated`));
            else if (fundedTrap) insights.push(window.mySimulation.t(`insight_trap`));
            else if (breach) insights.push(window.mySimulation.t(`insight_breach`));
            else if (!credibleTheory) insights.push(window.mySimulation.t(`insight_broad`));
            else insights.push(window.mySimulation.t(`insight_unproven`));

            if (discount >= this.START_DISCOUNT) insights.push(window.mySimulation.t(`insight_widened`));
            if (discountClosed) insights.push(window.mySimulation.t(`insight_closed`));
            if (ds.rejectedTrap) insights.push(window.mySimulation.t(`insight_discipline`));

            return {
                coherence: coherence,
                discount: discount,
                growth: growth,
                credibleTheory: credibleTheory,
                discountClosed: discountClosed,
                met: (credibleTheory && discountClosed && !fundedTrap && !breach),
                composite: composite,
                overallScore: composite,
                performance: performance,
                performanceKey: performanceKey,
                totalPeriods: history.length,
                insights: insights
            };
        }

        // v1.1.0: localized completion debrief (engine otherwise shows a generic fallback).
        formatCompletionMessage(summary) {
            const t = (k) => (window.mySimulation ? window.mySimulation.t(k) : k);
            const s = summary || {};
            const raw = (s.composite != null) ? s.composite : (s.overallScore != null ? s.overallScore : 0);
            const score = Math.max(0, Math.min(100, Math.round(Number(raw) || 0)));
            const grade = s.performanceKey ? t(s.performanceKey) : (s.performance || '');
            const badge = s.met
                ? `<span class="theorysim-cm-badge theorysim-cm-badge-ok">${t('cm_targets_met')}</span>`
                : `<span class="theorysim-cm-badge theorysim-cm-badge-miss">${t('cm_targets_missed')}</span>`;
            const kpi = (k, v, suf) => `<div class="theorysim-cm-kpi"><div class="theorysim-cm-kpi-val">${(v != null ? v : '—')}${suf || ''}</div><div class="theorysim-cm-kpi-lbl">${t(k)}</div></div>`;
            const ins = Array.isArray(s.insights) ? s.insights : [];
            const insHtml = ins.length
                ? `<div class="theorysim-cm-insights"><div class="theorysim-cm-ins-h">${t('cm_insights')}</div><ul>${ins.map((i) => `<li>${i}</li>`).join('')}</ul></div>`
                : '';
            return `
                <div class="theorysim-cm">
                    <div class="theorysim-cm-title">${t('cm_title')}</div>
                    <div class="theorysim-cm-scorewrap">
                        <div class="theorysim-cm-score">${score}<span class="theorysim-cm-score-max">/100</span></div>
                        <div class="theorysim-cm-grade">${grade}</div>
                        <div class="theorysim-cm-badges">${badge}</div>
                    </div>
                    <div class="theorysim-cm-kpis">
                        ${kpi('cm_kpi_coherence', s.coherence, '')}
                        ${kpi('cm_kpi_discount', s.discount, '%')}
                        ${kpi('cm_kpi_growth', s.growth, '')}
                    </div>
                    ${insHtml}
                </div>`;
        }

        getHint(state, results) {
