            if (ds.fundedVerdana) return window.mySimulation.t(`hint_trap`);
            if (ds.leverageBreach) return window.mySimulation.t(`hint_breach`);
            if (state.currentPeriod >= 2 && ds.coherence < 40) return window.mySimulation.t(`hint_broad`);
            if (state.currentPeriod >= 3 && ds.discount > 18) return window.mySimulation.t(`hint_discount`);
            if (ds.coherence >= this.TARGET_COHERENCE && ds.discount <= 15) return window.mySimulation.t(`hint_strong`);
            return null;
        }

